int decode_vop_header(Mpeg4DecContext *ctx, GetBitContext *gb) {
    if (get_bits_left(gb) < 0) {
        return 0;
    }

    ctx->avctx->pix_fmt = ctx->last_packed_palette ? PIX_FMT_PAL8 : ctx->is_packed ? PIX_FMT_BGR24 : PIX_FMT_YUV420P;
    ctx->time = get_bits(gb, 10);
    skip_bits(gb, 3);
    ctx->vop_time_increment = get_bits(gb, 11);
    skip_bits(gb, 2);

    if (show_bits(gb, 2) == 3) {
        skip_bits(gb, 2);
        ctx->vop_coding_type = get_bits(gb, 2) + 1;
    } else {
        ctx->vop_coding_type = get_bits(gb, 2) + 1;
    }

    if (ctx->vop_coding_type == 1) {
        ctx->f_code[0][0] = ctx->f_code[0][1] = ctx->f_code[1][0] = ctx->f_code[1][1] = 1;
    }

    if (ctx->vop_coding_type != 1) {
        ctx->f_code[0][0] = ctx->f_code[0][1] = ctx->f_code[1][0] = ctx->f_code[1][1] = 1;
        ctx->interlaced = 0;
        ctx->top_field_first = 0;
        ctx->alternate_vertical = 0;
    }

    if (ctx->vop_coding_type == 2 || ctx->vop_coding_type == 4) {
        ctx->intra_dc_precision = get_bits(gb, 4);
        ctx->load_intra_quantizer_matrix = get_bits1(gb);
        if (ctx->load_intra_quantizer_matrix) {
            for (int i = 0; i < 64; i++) {
                ctx->intra_matrix[scan_table[i]] = get_bits(gb, 8);
            }
        } else {
            memcpy(ctx->intra_matrix, default_intra_matrix, 64 * sizeof(int16_t));
        }
    }

    ctx->load_inter_quantizer_matrix = get_bits1(gb);
    if (ctx->load_inter_quantizer_matrix) {
        for (int i = 0; i < 64; i++) {
            ctx->inter_matrix[scan_table[i]] = get_bits(gb, 8);
        }
    } else {
        memcpy(ctx->inter_matrix, default_inter_matrix, 64 * sizeof(int16_t));
    }

    ctx->quant_precision = 5;
    ctx->dct_precision = get_bits1(gb);
    ctx->dct_type = get_bits1(gb);
    ctx->quant_type = get_bits1(gb);
    ctx->intra_vlc_format = get_bits1(gb);

    return 0;
}

int decode_vop_header(Mpeg4DecContext *ctx, GetBitContext *gb) {
    if (get_bits_left(gb) < 0)
        return 0;

    ctx->frame_type = get_bits1(gb);
    ctx->dct_type = get_bits1(gb);
    skip_bits(gb, 1); // Skip VOP structure bit

    int temporal_reference = get_bits(gb, 10);
    ctx->time_increment = temporal_reference;
    ctx->picture_type = get_bits(gb, 2);

    if (ctx->picture_type == 0) {
        ctx->reset_predictor = 1;
        init_scantable(ctx->intra_scantable, default_intra_scantable);
    } else if (ctx->picture_type == 1) {
        ctx->reset_predictor = 0;
        init_scantable(ctx->inter_scantable, default_inter_scantable);
    }

    load_default_matrices(ctx);
    process_user_data(ctx, gb);

    return 0;
}

int decode_vop_header(Mpeg4DecContext *ctx, GetBitContext *gb) {
    if (get_bits_left(gb) < 0) {
        return 0;
    }

    ctx->current_picture_ptr->f.key_frame = 0;
    ctx->picture_structure = 0;
    ctx->progressive_sequence = get_bits1(gb);
    ctx->progressive_frame    = get_bits1(gb);
    ctx->top_field_first      = get_bits1(gb);
    ctx->frame_pred_frame_dct = get_bits1(gb);
    ctx->full_pel_forward_vec = get_bits1(gb);
    ctx->full_pel_backward_vec = get_bits1(gb);

    skip_bits(gb, 5); // temporal reference

    ctx->vop_time_increment_resolution = get_bits(gb, 16);
    ctx->vop_time_increment = get_bits(gb, 16);

    ctx->vop_coding_type = get_bits(gb, 2);
    if (ctx->vop_coding_type == 0)
        ctx->vop_coding_type = 1;

    ctx->intra_dc_precision = get_bits(gb, 2);
    ctx->vop_fcode_forward  = get_bits(gb, 3) + 1;
    ctx->vop_fcode_backward = get_bits(gb, 3) + 1;

    skip_bits(gb, 1); // vop_quant

    ctx->alternate_scan = get_bits1(gb);

    if (ctx->alternate_scan)
        mpeg4_get_alternate_scan(gb, ctx->intra_scantable, ctx->inter_scantable);

    if (ctx->vop_coding_type == 1)
        ctx->first_slice = 1;

    // Load default matrices
    init_default_matrices(ctx);

    process_user_data(gb, ctx);

    return 0;
}

int decode_vop_header(Mpeg4DecContext *ctx, GetBitContext *gb) {
    if (get_bits_left(gb) < 0)
        return 0;

    ctx->pict_type = get_bits1(gb);
    skip_bits(gb, 1); // Skip random access indicator

    ctx->time_inc = get_bits(gb, 16);
    ctx->time = get_bits(gb, 16);
    ctx->vop_time_increment_resolution = get_bits(gb, 16);

    skip_bits(gb, 1); // Skip VOP coding type
    skip_bits(gb, 1); // Skip VOP shape

    ctx->vop_fcode_forward = get_bits(gb, 3) + 1;
    ctx->vop_fcode_backward = get_bits(gb, 3) + 1;

    skip_bits(gb, 1); // Skip VOP complexity

    ctx->vop_quant = get_bits(gb, 5);
    ctx->vop_quant_type = get_bits1(gb);

    if (ctx->pict_type == 0) {
        ctx->pred_dquant = 0;
        ctx->pred_acdc = 0;
    }

    ctx->default_matrix = 1;

    return 0;
}

int decode_vop_header(Mpeg4DecContext *ctx, GetBitContext *gb) {
    if (get_bits_left(gb) < 0)
        return 0;

    ctx->pict_type = get_bits1(gb);
    ctx->f_code = 1;
    ctx->intra_dc_precision = 0;
    ctx->top_field_first = get_bits1(gb);
    ctx->alternate_scan = 0;

    skip_bits(gb, 1); // vop_time_increment_resolution
    skip_bits(gb, 1); // vbv_delay

    ctx->time_inc_bits = 0;
    ctx->time_increment = get_bits(gb, ctx->time_inc_bits);
    ctx->time_base += ctx->time_increment;

    if (ctx->pict_type == 1) {
        ctx->f_code = get_bits1(gb) + 1;
        ctx->intra_dc_precision = get_bits1(gb);
        ctx->alternate_vertical_scan = get_bits1(gb);
    }

    ctx->vop_width = ctx->width;
    ctx->vop_height = ctx->height;

    ctx->intra_vlc_threshold = 0;

    for (int i = 0; i < 6; i++) {
        ctx->intra_scantable[i].permutated = 0;
        memcpy(ctx->intra_scantable[i].scantable, ff_zigzag_direct, sizeof(int) * 64);
    }

    for (int i = 0; i < 6; i++) {
        ctx->inter_scantable[i].permutated = 0;
        memcpy(ctx->inter_scantable[i].scantable, ff_zigzag_direct, sizeof(int) * 64);
    }

    ctx->load_intra_matrices = 0;
    ctx->load_inter_matrices = 0;

    return 0;
}
